import{_ as e,o as d,c as a,a3 as r}from"./chunks/framework.B8xISX-C.js";const p=JSON.parse('{"title":"Rules catalogs (patch only)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rules.md","filePath":"reference/rules.md"}'),o={name:"reference/rules.md"};function s(l,t,n,i,c,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="rules-catalogs-patch-only" tabindex="-1">Rules catalogs (patch only) <a class="header-anchor" href="#rules-catalogs-patch-only" aria-label="Permalink to &quot;Rules catalogs (patch only)&quot;">​</a></h1><p>These catalogs hold the game&#39;s rules: one parameter record (key <code>standard</code> or the catalog&#39;s own key) or a fixed set of records. Mods change them with patch rows; they cannot add records to them. Values may change freely within the field&#39;s range; the length of a fixed table may not.</p><h2 id="catalogs" tabindex="-1">Catalogs <a class="header-anchor" href="#catalogs" aria-label="Permalink to &quot;Catalogs&quot;">​</a></h2><p>Each catalog has a page with its records, the type of every field and the base value of each.</p><table tabindex="0"><thead><tr><th>Catalog</th><th>Records</th><th>Fields</th></tr></thead><tbody><tr><td><a href="./rules-ai-objectives">ai-objectives</a></td><td>1</td><td>20</td></tr><tr><td><a href="./rules-ai-personality">ai-personality</a></td><td>1</td><td>94</td></tr><tr><td><a href="./rules-ai-tuning">ai-tuning</a></td><td>1</td><td>139</td></tr><tr><td><a href="./rules-assimilation-rules">assimilation-rules</a></td><td>1</td><td>3</td></tr><tr><td><a href="./rules-audience-rules">audience-rules</a></td><td>1</td><td>312</td></tr><tr><td><a href="./rules-build-lists">build-lists</a></td><td>11</td><td>2</td></tr><tr><td><a href="./rules-cheat-codes">cheat-codes</a></td><td>1</td><td>3</td></tr><tr><td><a href="./rules-colonize-rules">colonize-rules</a></td><td>1</td><td>13</td></tr><tr><td><a href="./rules-colony-economy">colony-economy</a></td><td>1</td><td>49</td></tr><tr><td><a href="./rules-combat-rules">combat-rules</a></td><td>1</td><td>426</td></tr><tr><td><a href="./rules-council-rules">council-rules</a></td><td>1</td><td>35</td></tr><tr><td><a href="./rules-difficulty">difficulty</a></td><td>5</td><td>15</td></tr><tr><td><a href="./rules-diplomacy-rules">diplomacy-rules</a></td><td>1</td><td>201</td></tr><tr><td><a href="./rules-drives">drives</a></td><td>6</td><td>5</td></tr><tr><td><a href="./rules-espionage-rules">espionage-rules</a></td><td>1</td><td>28</td></tr><tr><td><a href="./rules-event-rules">event-rules</a></td><td>1</td><td>101</td></tr><tr><td><a href="./rules-events">events</a></td><td>38</td><td>9</td></tr><tr><td><a href="./rules-finance-rules">finance-rules</a></td><td>1</td><td>26</td></tr><tr><td><a href="./rules-fuel-cells">fuel-cells</a></td><td>5</td><td>3</td></tr><tr><td><a href="./rules-galaxy-gen">galaxy-gen</a></td><td>1</td><td>259</td></tr><tr><td><a href="./rules-governments">governments</a></td><td>8</td><td>29</td></tr><tr><td><a href="./rules-governor-policies">governor-policies</a></td><td>3</td><td>32</td></tr><tr><td><a href="./rules-history-rules">history-rules</a></td><td>1</td><td>8</td></tr><tr><td><a href="./rules-hulls">hulls</a></td><td>9</td><td>26</td></tr><tr><td><a href="./rules-leader-rules">leader-rules</a></td><td>1</td><td>300</td></tr><tr><td><a href="./rules-leaders">leaders</a></td><td>67</td><td>15</td></tr><tr><td><a href="./rules-message-rules">message-rules</a></td><td>1</td><td>3</td></tr><tr><td><a href="./rules-monster-rules">monster-rules</a></td><td>1</td><td>24</td></tr><tr><td><a href="./rules-monsters">monsters</a></td><td>10</td><td>10</td></tr><tr><td><a href="./rules-movement">movement</a></td><td>1</td><td>34</td></tr><tr><td><a href="./rules-planet-mod-rules">planet-mod-rules</a></td><td>1</td><td>18</td></tr><tr><td><a href="./rules-planet-types">planet-types</a></td><td>10</td><td>11</td></tr><tr><td><a href="./rules-population-rules">population-rules</a></td><td>1</td><td>31</td></tr><tr><td><a href="./rules-production-rules">production-rules</a></td><td>1</td><td>23</td></tr><tr><td><a href="./rules-race-rules">race-rules</a></td><td>1</td><td>13</td></tr><tr><td><a href="./rules-relations-matrix">relations-matrix</a></td><td>14</td><td>3</td></tr><tr><td><a href="./rules-research">research</a></td><td>1</td><td>16</td></tr><tr><td><a href="./rules-score">score</a></td><td>1</td><td>24</td></tr><tr><td><a href="./rules-settings">settings</a></td><td>35</td><td>4</td></tr><tr><td><a href="./rules-ship-design">ship-design</a></td><td>1</td><td>81</td></tr><tr><td><a href="./rules-ship-lifecycle">ship-lifecycle</a></td><td>1</td><td>23</td></tr><tr><td><a href="./rules-star-types">star-types</a></td><td>7</td><td>9</td></tr><tr><td><a href="./rules-start-state">start-state</a></td><td>1</td><td>244</td></tr><tr><td><a href="./rules-transport-rules">transport-rules</a></td><td>1</td><td>20</td></tr><tr><td><a href="./rules-troop-units">troop-units</a></td><td>1</td><td>68</td></tr><tr><td><a href="./rules-vaelori-designs">vaelori-designs</a></td><td>13</td><td>10</td></tr><tr><td><a href="./rules-vaelori-rules">vaelori-rules</a></td><td>1</td><td>39</td></tr><tr><td><a href="./rules-weapon-mods">weapon-mods</a></td><td>14</td><td>8</td></tr></tbody></table><h2 id="starting-technology" tabindex="-1">Starting technology <a class="header-anchor" href="#starting-technology" aria-label="Permalink to &quot;Starting technology&quot;">​</a></h2><p>Each of the four <code>levels</code> (<code>preWarp</code>, <code>average</code>, <code>postWarp</code>, <code>advanced</code>) has an <code>alsoKnown</code> list: technology every empire starting at that level knows besides the level&#39;s own grant. An entry is <code>{ &quot;field&quot;: &lt;tech field key&gt; }</code> (the field counts as researched and all its applications are known) or <code>{ &quot;app&quot;: &lt;application key&gt; }</code> (that application alone; its field stays researchable for the others), and may carry <code>&quot;when&quot;: { picks, governments, vaelori }</code>, the same condition the removal rows use, evaluated for the starting empire. The base game lists nothing.</p><p>The order for an empire starting at a level: the level&#39;s own grant, then the <code>alsoKnown</code> entries whose condition holds, then the level&#39;s <code>allAppsExcluded</code> removes its applications (excluded wins over also known), then applications the empire is barred from are never granted (barred wins). A level takes nothing from another through <code>baseLevel</code>: Post-Warp does not take the Average list; a mod lists both.</p><p>Add to one level with a keyed path (below): <code>{ &quot;op&quot;: &quot;append&quot;, &quot;catalog&quot;: &quot;start-state&quot;, &quot;key&quot;: &quot;classic&quot;, &quot;path&quot;: &quot;levels.advanced.alsoKnown&quot;, &quot;value&quot;: { &quot;field&quot;: &quot;yourname.my_mod.some_field&quot; } }</code>.</p><h2 id="keyed-arrays" tabindex="-1">Keyed arrays <a class="header-anchor" href="#keyed-arrays" aria-label="Permalink to &quot;Keyed arrays&quot;">​</a></h2><p>A path never takes a list index. A catalog may declare arrays of records with a unique key field as keyed: in a patch path the segment after the array selects the element whose key field equals it, so <code>levels.advanced.alsoKnown</code> is the Advanced level&#39;s list. It works in <code>set</code>, <code>append</code>, <code>insertAfter</code>, <code>removeValue</code> and in <code>expect</code>. An unknown element is <code>patch-no-match</code> (skipped with <code>optional</code>). Rows on different elements never conflict, two appends to the same list compose, and a row on the whole array conflicts with rows on its elements from another package. Only the arrays listed on a catalog&#39;s page are keyed; the others are addressed as a whole.</p><h2 id="removal-rows-and-exclusive-technology" tabindex="-1">Removal rows and exclusive technology <a class="header-anchor" href="#removal-rows-and-exclusive-technology" aria-label="Permalink to &quot;Removal rows and exclusive technology&quot;">​</a></h2><p>A row <code>{ &quot;when&quot;?: &lt;condition&gt;, &quot;unless&quot;?: { &quot;picks&quot;?: [...], &quot;races&quot;?: [...] }, &quot;apps&quot;: [...] }</code> (at least one of <code>when</code> and <code>unless</code>) removes its applications from the empires it applies to: the empire matches <code>when</code> (absent: every empire) and does not match <code>unless</code>. <code>unless.picks</code> spares an empire that has any listed race pick (pick-bound: a custom race that takes the pick qualifies, and the pick&#39;s price is the cost of the technology). <code>unless.races</code> spares an empire that plays the race record of any listed key (race-bound: a custom race keeps the record of its portrait race and qualifies only when that is the listed race). Appending <code>{ &quot;unless&quot;: { &quot;picks&quot;: [&quot;yourname.my_mod.some_pick&quot;] }, &quot;apps&quot;: [&quot;yourname.my_mod.some_app&quot;] }</code> makes the application exclusive to empires with the pick.</p><p>A row with <code>unless</code> is an exclusivity row: no route can bring its applications to an empire it applies to (research, start knowledge, trades and gifts, demands, theft, scrapping captured ships, ground conquest, finds, leaders, cheats). A field none of whose applications an empire can gain is passed over silently for it: never offered, never completed, never counted, and the computer players never value it. The base removals (Lithovore, Tolerant, Unification) keep the original game&#39;s behaviour on trades, theft and finds.</p>',14)])])}const f=e(o,[["render",s]]);export{p as __pageData,f as default};
